__NUXT_JSONP__("/fr/about", (function(a){return {data:[{details:{slug:"fr",pageTitle:"Qu'est-ce que MLI? | Mentor Language Institute",pageDescription:"Mentor Language Institute a été fondé en 2002 et est situé dans deux quartiers populaires: Westwood et Hollywood.",section1:{title:"Qu'est-ce que MLI?",description:["Mentor Language Institute a été fondé en 2002 et est situé dans deux quartiers populaires: Westwood et Hollywood.\u003Cbr \u002F\u003ENous aidons les étudiants du monde entier à améliorer leur anglais."]},section2:{image:"\u002Fimages\u002Fwhat-is-mli\u002Fabout\u002Fpay-less-for-quality-classes.jpg",title:"Payer moins pour les classes de qualité",description:["Nous valorisons deux choses: \u003Cb\u003E\"Qualité de l'éducation\"\u003C\u002Fb\u003E  et  \u003Cb\u003E\"Prix\".\u003Cb\u003E","L'anglais est la langue globale et un outil nécessaire pour la communication avec les gens du monde entier. Notre espoir est que les étudiants internationaux acquièrent des compétences en anglais pour réussir dans le monde. Pour cette raison, nous nous concentrons sur la qualité des classes à des prix raisonnables."]},section3:{image:"\u002Fimages\u002Fwhat-is-mli\u002Fabout\u002Fmli-staff.jpg",title:"Jusqu'en 2020, plus de 17 000 étudiants ont choisi et obtenu leur diplôme à MLI.",description:["Nous offrons des cours d'ESL (programme d'anglais général avec 7 niveaux comprenant grammaire\u002Fexpression écrite, lecture\u002Fvocabulaire et compréhension à l'audition\u002Fexpression orale), TOEFL®, IELTS™ (pour les étudiants qui veulent transférer à l'université) et TOEIC®.","Beaucoup d'étudiants ont également continué à étudier dans des universités ou des collèges aux États-Unis comme UCLA, USC et Santa Monica College."],lists:[{link:"\u002Ffr\u002Ffeature",image:a,text:"5 raisons pour lesquelles les gens choisissent MLI"},{link:"\u002Ffr\u002Fcompany",image:a,text:"Informations sur la compagnie"},{link:"\u002Ffr\u002Fimage-gallery",image:a,text:"Galerie photo\u002Fvidéo"}]},dir:"\u002Fabout",path:"\u002Fabout\u002Ffr",extension:".json",createdAt:"2026-10-22T16:31:28.446Z",updatedAt:"2025-05-26T12:06:27.572Z"}}],fetch:{},mutations:void 0}}("\u002Fimages\u002Ficons\u002Fboxed-arrow.svg")));